SELECT gen_random_uuid()::text, 'formula', '$\omega$', 'Successive Over-Relaxation', '$x_i^{\text{new}} = \omega\,x_i^{\text{GS}} + (1 - \omega)\,x_i^{\text{old}}$', NULL, 'A weighted step past (or short of) the Gauss-Seidel value to speed convergence.', '[{"symbol":"$\\omega$","meaning":"the relaxation factor, between 0 and 2"},{"symbol":"$x_i^{\\text{GS}}$","meaning":"the Gauss-Seidel value"}]'::jsonb, '$\omega = 1$ is Gauss-Seidel; $1 < \omega < 2$ over-relaxes.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'jacobi and gauss-seidel' AND s."active"), NULL, true, 'PENDING', now(), now()
