SELECT gen_random_uuid()::text, 'formula', '$y$', 'Linear Interpolation', '$y = y_0 + \frac{y_1 - y_0}{x_1 - x_0}(x - x_0)$', NULL, 'A value between two table entries, read off the straight line joining them.', '[{"symbol":"$(x_0, y_0), (x_1, y_1)$","meaning":"the table entries either side"}]'::jsonb, 'Steam tables and log tables are read this way.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'newton''s interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
