SELECT gen_random_uuid()::text, 'formula', '$f[x_0, x_1]$', 'Divided Differences', '$f[x_i, x_{i+1}] = \frac{f(x_{i+1}) - f(x_i)}{x_{i+1} - x_i},\qquad f[x_0, \ldots, x_k] = \frac{f[x_1, \ldots, x_k] - f[x_0, \ldots, x_{k-1}]}{x_k - x_0}$', NULL, 'The table of slopes, slopes of slopes, and so on, that builds Newton''s polynomial.', '[{"symbol":"$(x_i, y_i)$","meaning":"the tabulated points"}]'::jsonb, 'Divide by the span of the WHOLE set of points at each level, not by the step.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'newton''s interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics'
