SELECT gen_random_uuid()::text, 'formula', '$P_n(x)$', 'Newton''s Divided-Difference Polynomial', '$P_n(x) = f[x_0] + f[x_0, x_1](x - x_0) + f[x_0, x_1, x_2](x - x_0)(x - x_1) + \cdots$', NULL, 'The interpolating polynomial built from the top diagonal of the divided-difference table.', '[{"symbol":"$(x_i, y_i)$","meaning":"the tabulated points"}]'::jsonb, 'Adding a point adds one term; the earlier terms stay.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'newton''s interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
