SELECT gen_random_uuid()::text, 'formula', '$P(x_0 + sh)$', 'Newton''s Forward-Difference Formula', '$P(x_0 + sh) = y_0 + s\,\Delta y_0 + \frac{s(s - 1)}{2!}\Delta^2 y_0 + \frac{s(s - 1)(s - 2)}{3!}\Delta^3 y_0 + \cdots$', NULL, 'Interpolation on equally spaced points, for a value near the start of the table.', '[{"symbol":"$s$","meaning":"$\\frac{x - x_0}{h}$"},{"symbol":"$\\Delta y_0$","meaning":"forward differences, $\\Delta y_i = y_{i+1} - y_i$"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, '$s$ counts steps from $x_0$, so it may be a fraction.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'newton''s interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics'
