SELECT gen_random_uuid()::text, 'formula', '$P(x_n + sh)$', 'Newton''s Backward-Difference Formula', '$P(x_n + sh) = y_n + s\,\nabla y_n + \frac{s(s + 1)}{2!}\nabla^2 y_n + \frac{s(s + 1)(s + 2)}{3!}\nabla^3 y_n + \cdots$', NULL, 'Interpolation on equally spaced points, for a value near the end of the table.', '[{"symbol":"$s$","meaning":"$\\frac{x - x_n}{h}$, negative inside the table"},{"symbol":"$\\nabla y_n$","meaning":"backward differences, $\\nabla y_i = y_i - y_{i-1}$"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, 'The factors grow as s, s + 1, s + 2: the signs differ from the forward formula.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'newton''s interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
