SELECT gen_random_uuid()::text, 'formula', '$P(x)$', 'Lagrange Interpolating Polynomial', '$P(x) = \sum_{i=0}^{n} y_i L_i(x),\qquad L_i(x) = \prod_{j \ne i}\frac{x - x_j}{x_i - x_j}$', NULL, 'The polynomial through n + 1 points, written as a weighted sum of the y-values.', '[{"symbol":"$(x_i, y_i)$","meaning":"the tabulated points"}]'::jsonb, 'It is the same polynomial as Newton''s, written another way; points need not be equally spaced.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'lagrange interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
