SELECT gen_random_uuid()::text, 'formula', '$L_i(x_j)$', 'Lagrange Basis Properties', '$L_i(x_j) = \begin{cases}1 & i = j\\ 0 & i \ne j\end{cases},\qquad \sum_{i} L_i(x) = 1$', NULL, 'Each basis polynomial is 1 at its own point and 0 at the others; together they add to 1.', '[{"symbol":"$L_i$","meaning":"the Lagrange basis polynomials"}]'::jsonb, 'A quick check of your arithmetic: the weights at any x must sum to 1.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'lagrange interpolation' AND s."active"), NULL, true, 'PENDING', now(), now()
