SELECT gen_random_uuid()::text, 'formula', '$A^{\mathsf T}A\,\vec{c} = A^{\mathsf T}\vec{y}$', 'Normal Equations', '$\textstyle\sum y = na + b\sum x,\quad \sum xy = a\sum x + b\sum x^2;\qquad A^{\mathsf T}A\,\vec{c} = A^{\mathsf T}\vec{y}$', NULL, 'The linear system whose solution is the least-squares fit, for a line or any polynomial.', '[{"symbol":"$A$","meaning":"one row per point, one column per term of the model"},{"symbol":"$\\vec{c}$","meaning":"the coefficients"}]'::jsonb, 'For a parabola add $\sum x^2y = a\sum x^2 + b\sum x^3 + c\sum x^4$ and the matching first two.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'least-squares curve fitting' AND s."active"), NULL, true, 'PENDING', now(), now()
