SELECT gen_random_uuid()::text, 'formula', '$r^2$', 'Coefficient of Determination', '$r^2 = 1 - \frac{S_r}{S_t},\qquad S_r = \sum(y_i - \hat{y}_i)^2,\quad S_t = \sum(y_i - \bar{y})^2$', NULL, 'The share of the spread in y that the fit explains.', '[{"symbol":"$\\hat{y}_i$","meaning":"the fitted values"},{"symbol":"$\\bar{y}$","meaning":"the mean of the data"}]'::jsonb, '$r^2 = 1$ is a perfect fit; for a line, $r$ is the correlation coefficient.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'least-squares curve fitting' AND s."active"), NULL, true, 'PENDING', now(), now()
