SELECT gen_random_uuid()::text, 'formula', '$s_{y/x}$', 'Standard Error of the Estimate', '$s_{y/x} = \sqrt{\frac{S_r}{n - (m + 1)}}$', NULL, 'The typical size of a data point''s miss from the fitted curve.', '[{"symbol":"$S_r$","meaning":"the sum of squared residuals"},{"symbol":"$m$","meaning":"the degree of the fitted polynomial (1 for a line)"}]'::jsonb, 'A line uses n − 2.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'least-squares curve fitting' AND s."active"), NULL, true, 'PENDING', now(), now()
