SELECT gen_random_uuid()::text, 'formula', '$f''(x)$', 'Forward and Backward Differences', '$f''(x) \approx \frac{f(x + h) - f(x)}{h},\qquad f''(x) \approx \frac{f(x) - f(x - h)}{h}\qquad O(h)$', NULL, 'The slope from one step ahead or behind; the error shrinks in proportion to h.', '[{"symbol":"$f$","meaning":"the function"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, 'The error is about $\frac{h}{2}f''''(x)$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'numerical differentiation' AND s."active"), NULL, true, 'PENDING', now(), now()
