SELECT gen_random_uuid()::text, 'formula', '$f''(x)$', 'Central Difference First Derivative', '$f''(x) \approx \frac{f(x + h) - f(x - h)}{2h}\qquad O(h^2)$', NULL, 'The slope from the points either side: much more accurate than a one-sided difference.', '[{"symbol":"$f$","meaning":"the function"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, 'Halving h quarters the error. Too small an h lets round-off take over.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'numerical differentiation' AND s."active"), NULL, true, 'PENDING', now(), now()
