SELECT gen_random_uuid()::text, 'formula', '$D$', 'Richardson Extrapolation', '$D \approx \frac{4D(h/2) - D(h)}{3}$', NULL, 'Combine two estimates of an O(h²) method to cancel the leading error term.', '[{"symbol":"$D(h)$","meaning":"an $O(h^2)$ estimate with step $h$"}]'::jsonb, 'For an $O(h^p)$ method use $\frac{2^pD(h/2) - D(h)}{2^p - 1}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'numerical differentiation' AND s."active"), NULL, true, 'PENDING', now(), now()
