SELECT gen_random_uuid()::text, 'formula', '$S_{3/8}$', 'Simpson''s Three-Eighths Rule', '$\int_a^b f\,dx \approx \frac{3h}{8}\left[y_0 + 3y_1 + 3y_2 + 2y_3 + 3y_4 + \cdots + 3y_{n-1} + y_n\right]$', NULL, 'Estimates an integral with cubic pieces over three strips at a time.', '[{"symbol":"$h$","meaning":"the step or strip width"},{"symbol":"$y_i$","meaning":"function values"},{"symbol":"$n$","meaning":"the number of strips, a multiple of 3"}]'::jsonb, 'With an odd number of strips, use $\frac38$ on three of them and $\frac13$ on the rest.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'trapezoidal and simpson''s rules' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
