SELECT gen_random_uuid()::text, 'formula', '$E$', 'Errors of the Trapezoidal and Simpson Rules', '$E_T = -\frac{(b - a)h^2}{12}f''''(\xi),\qquad E_S = -\frac{(b - a)h^4}{180}f^{(4)}(\xi)$', NULL, 'The trapezoidal rule''s error shrinks with h², Simpson''s with h⁴.', '[{"symbol":"$h$","meaning":"the step or strip width"},{"symbol":"$\\xi$","meaning":"some point in $[a, b]$"}]'::jsonb, 'Simpson''s rule is exact for cubics; the trapezoidal rule only for straight lines.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'trapezoidal and simpson''s rules' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
