SELECT gen_random_uuid()::text, 'formula', '$M_n$', 'Midpoint Rule', '$\int_a^b f\,dx \approx h\sum_{i=1}^{n} f\!\left(\frac{x_{i-1} + x_i}{2}\right)$', NULL, 'Each strip''s height is the function at its middle.', '[{"symbol":"$h$","meaning":"the step or strip width"},{"symbol":"$n$","meaning":"the number of strips"}]'::jsonb, 'Its error is about half the trapezoidal rule''s, with the opposite sign: $E_M \approx -\frac12E_T$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'trapezoidal and simpson''s rules' AND s."active"), NULL, true, 'PENDING', now(), now()
