SELECT gen_random_uuid()::text, 'formula', '$R$', 'Romberg Integration', '$I \approx \frac{4\,T(h/2) - T(h)}{3},\qquad \text{then } \frac{16\,I(h/2) - I(h)}{15}, \ldots$', NULL, 'Richardson extrapolation applied to the trapezoidal rule, level by level.', '[{"symbol":"$T(h)$","meaning":"the trapezoidal estimate with strip width h"}]'::jsonb, 'The first level is exactly Simpson''s one-third rule.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'trapezoidal and simpson''s rules' AND s."active"), NULL, true, 'PENDING', now(), now()
