SELECT gen_random_uuid()::text, 'formula', '$G_2$', 'Two-Point Gauss-Legendre Quadrature', '$\int_{-1}^{1} f\,dx \approx f\!\left(-\tfrac{1}{\sqrt3}\right) + f\!\left(\tfrac{1}{\sqrt3}\right);\quad x = \tfrac{b + a}{2} + \tfrac{b - a}{2}t,\ dx = \tfrac{b - a}{2}dt$', NULL, 'Two well-chosen points integrate any cubic exactly.', '[{"symbol":"$t$","meaning":"the variable on $[-1, 1]$"}]'::jsonb, 'Map $[a, b]$ to $[-1, 1]$ first, and multiply by $\frac{b - a}{2}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'trapezoidal and simpson''s rules' AND s."active"), NULL, true, 'PENDING', now(), now()
