SELECT gen_random_uuid()::text, 'formula', '$y_{n+1}$', 'Heun''s Method', '$y_{n+1} = y_n + \frac{h}{2}\left[f(x_n, y_n) + f\big(x_{n+1},\ y_n + h f(x_n, y_n)\big)\right]$', NULL, 'Improved Euler: average the slope at the start and at an Euler-predicted end.', '[{"symbol":"$f(x, y)$","meaning":"the slope $y''$"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, 'It is a second-order Runge-Kutta method: predict, then correct.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'euler and runge-kutta methods' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics'
