SELECT gen_random_uuid()::text, 'formula', '$y_{n+1}$', 'Midpoint Method for an ODE', '$y_{n+1} = y_n + h\,f\!\left(x_n + \tfrac{h}{2},\ y_n + \tfrac{h}{2}f(x_n, y_n)\right)$', NULL, 'Step with the slope found halfway across the interval.', '[{"symbol":"$f(x, y)$","meaning":"the slope $y''$"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, 'Also second order, like Heun''s method (modified Euler in some texts).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'euler and runge-kutta methods' AND s."active"), NULL, true, 'PENDING', now(), now()
