SELECT gen_random_uuid()::text, 'formula', '$y_{n+1}$', 'Fourth-Order Runge-Kutta Method', '$y_{n+1} = y_n + \frac{h}{6}(k_1 + 2k_2 + 2k_3 + k_4)$; $k_1 = f(x_n, y_n),\ k_2 = f(x_n + \frac{h}{2}, y_n + \frac{h}{2}k_1),\ k_3 = f(x_n + \frac{h}{2}, y_n + \frac{h}{2}k_2),\ k_4 = f(x_n + h, y_n + hk_3)$', NULL, 'The standard method for ODEs: four slopes per step, weighted 1, 2, 2, 1.', '[{"symbol":"$f(x, y)$","meaning":"the slope $y''$"},{"symbol":"$h$","meaning":"the step or strip width"}]'::jsonb, 'Use radians, and carry many digits through each k.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'euler and runge-kutta methods' AND s."active"), NULL, true, 'PENDING', now(), now()
