SELECT gen_random_uuid()::text, 'formula', '$O(h^p)$', 'Order of Accuracy of ODE Methods', '$\text{global error: Euler } O(h),\quad \text{Heun / midpoint } O(h^2),\quad \text{RK4 } O(h^4)$', NULL, 'Halving the step cuts the error by 2, 4 or 16 for these methods.', '[{"symbol":"$h$","meaning":"the step or strip width"},{"symbol":"$p$","meaning":"the order of the method"}]'::jsonb, 'The local error per step is one order higher, $O(h^{p+1})$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'euler and runge-kutta methods' AND s."active"), NULL, true, 'PENDING', now(), now()
