SELECT gen_random_uuid()::text, 'formula', '$R$', 'Golden-Section Search', '$x_1 = a + R(b - a),\quad x_2 = b - R(b - a),\qquad R = \frac{\sqrt5 - 1}{2} \approx 0.618$', NULL, 'Narrow the interval round an optimum, reusing one point each step.', '[{"symbol":"$[a, b]$","meaning":"an interval with one maximum or minimum"}]'::jsonb, 'Each step keeps 61.8% of the interval; for a minimum, drop the side of the larger value.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'optimization' AND s."active"), NULL, true, 'PENDING', now(), now()
