SELECT gen_random_uuid()::text, 'formula', '$x_{n+1}$', 'Newton''s Method for an Optimum', '$x_{n+1} = x_n - \frac{f''(x_n)}{f''''(x_n)}$', NULL, 'Newton-Raphson applied to $f''(x) = 0$, to find where a function levels off.', '[{"symbol":"$f$","meaning":"the function"},{"symbol":"$x_n$","meaning":"the current estimate"}]'::jsonb, 'It finds maxima and minima alike: check the sign of $f''''$ at the answer.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'optimization' AND s."active"), NULL, true, 'PENDING', now(), now()
