SELECT gen_random_uuid()::text, 'formula', '$x_3$', 'Parabolic Interpolation for an Optimum', '$x_3 = \frac{f_0(x_1^2 - x_2^2) + f_1(x_2^2 - x_0^2) + f_2(x_0^2 - x_1^2)}{2\left[f_0(x_1 - x_2) + f_1(x_2 - x_0) + f_2(x_0 - x_1)\right]}$', NULL, 'The vertex of the parabola through three points: the next estimate of the optimum.', '[{"symbol":"$x_0, x_1, x_2$","meaning":"three points near the optimum"},{"symbol":"$f_i$","meaning":"$f(x_i)$"}]'::jsonb, 'For a quadratic function it is exact in one step.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'optimization' AND s."active"), NULL, true, 'PENDING', now(), now()
