SELECT gen_random_uuid()::text, 'formula', '$\vec{x}_{k+1}$', 'Steepest Descent', '$\vec{x}_{k+1} = \vec{x}_k - \alpha\,\nabla f(\vec{x}_k)$', NULL, 'Step downhill along the negative gradient to minimise a function of several variables.', '[{"symbol":"$\\nabla f$","meaning":"the gradient"},{"symbol":"$\\alpha$","meaning":"the step length"}]'::jsonb, 'To maximise, step along +∇f (steepest ascent). Too large a step overshoots.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Numerical Methods & Analysis' AND t."subject" = 'Mathematics' AND s."normKey" = 'optimization' AND s."active"), NULL, true, 'PENDING', now(), now()
